-- RB Collect tables (waitlist-db, binding DB). Safe to run any number of times: every statement is
-- CREATE ... IF NOT EXISTS or INSERT OR IGNORE, so it never overwrites what the owner has edited.
-- artist-router runs this on first use (rb-site-updates/patch_rewards.py) and RB Command runs it when a
-- Rewards table is missing (rb-command-updates/patch_rewards_admin.py). Statements end with ";" + newline.
CREATE TABLE IF NOT EXISTS reward_config (key TEXT PRIMARY KEY, value TEXT, label TEXT, help TEXT, sort_order INTEGER NOT NULL DEFAULT 0, updated_at TEXT);
CREATE TABLE IF NOT EXISTS reward_prizes (id INTEGER PRIMARY KEY AUTOINCREMENT, set_key TEXT NOT NULL UNIQUE, set_label TEXT NOT NULL, name TEXT NOT NULL, description TEXT, quantity INTEGER NOT NULL DEFAULT 0, remaining INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'draft', sort_order INTEGER NOT NULL DEFAULT 0, image_url TEXT, updated_at TEXT);
CREATE TABLE IF NOT EXISTS reward_pieces (piece_key TEXT PRIMARY KEY, set_key TEXT NOT NULL, label TEXT NOT NULL, rare INTEGER NOT NULL DEFAULT 0, sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS reward_players (id TEXT PRIMARY KEY, clerk_user_id TEXT NOT NULL UNIQUE, email_norm TEXT, email_at TEXT, ref_code TEXT NOT NULL UNIQUE, referred_by TEXT, created_at TEXT NOT NULL, daily_at TEXT);
CREATE INDEX IF NOT EXISTS reward_players_email ON reward_players (email_norm);
CREATE TABLE IF NOT EXISTS reward_awards (id TEXT PRIMARY KEY, player_id TEXT NOT NULL, source TEXT NOT NULL, source_ref TEXT NOT NULL UNIQUE, plays INTEGER NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS reward_awards_player ON reward_awards (player_id, source);
CREATE TABLE IF NOT EXISTS reward_draws (id TEXT PRIMARY KEY, player_id TEXT NOT NULL, set_key TEXT NOT NULL, piece_key TEXT NOT NULL, rare INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS reward_draws_player ON reward_draws (player_id, set_key);
CREATE INDEX IF NOT EXISTS reward_draws_rare ON reward_draws (set_key, rare);
CREATE TABLE IF NOT EXISTS reward_claims (id TEXT PRIMARY KEY, player_id TEXT NOT NULL, set_key TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'requested', email TEXT, created_at TEXT NOT NULL, updated_at TEXT, notes TEXT, UNIQUE (player_id, set_key));
CREATE TABLE IF NOT EXISTS reward_codes (code TEXT PRIMARY KEY, label TEXT, plays INTEGER NOT NULL DEFAULT 1, max_uses INTEGER NOT NULL DEFAULT 1, uses INTEGER NOT NULL DEFAULT 0, expires_at TEXT, created_at TEXT DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS reward_rate (player_id TEXT NOT NULL, minute TEXT NOT NULL, n INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (player_id, minute));
