INSERT OR IGNORE INTO reward_config (key, value, label, help, sort_order) VALUES ('enabled', 'off', 'Game switched on', 'on or off. While off the board says RB Collect is coming soon and nobody can play, claim or redeem codes.', 1), ('starts_at', '', 'Start', 'When plays open. A date like 2026-11-01 (midnight Pacific) or a date and time with offset like 2026-11-01T18:00-07:00. Empty means as soon as the game is switched on.', 2), ('ends_at', '', 'End', 'When plays stop. A date like 2026-12-31 (to 11:59pm Pacific that day) or a date and time with offset. Empty means no end date is published.', 3), ('eligibility', 'Open to legal residents of the United States who are 18 or older.', 'Who can play', 'Shown in the official rules. Have this reviewed before switching the game on.', 4), ('rare_odds', '50', 'Rare piece odds (1 in N)', 'Each play has a 1 in N chance of being a rare piece, shared evenly across the live sets that still have prizes. Whole number, 2 or more.', 5), ('plays_daily', '1', 'Free plays every day', 'Free plays every signed-in player gets each day (resets at midnight Pacific). No purchase needed.', 10), ('plays_welcome', '3', 'Welcome plays', 'Plays on a player''s first sign-in while the game is on.', 11), ('plays_signup', '2', 'Plays for joining the RB list', 'One time, when the player''s verified email is on the RB list (signups).', 12), ('plays_membership_request', '5', 'Plays per membership request', 'One time per membership tier, when the player''s verified email joined a waitlist or applied at /memberships.', 13), ('plays_member_daily', '2', 'Extra daily plays for active members', 'Added each day for players with an active RB Studio membership.', 14), ('plays_per_5_dollars_given', '2', 'Plays per $5 given', 'For each $5 of a paid contribution at /fund (counted per contribution).', 15), ('contribution_cap', '40', 'Most plays per contribution', 'Upper limit of plays from one contribution.', 16), ('plays_per_10_dollars_spent', '1', 'Plays per $10 spent in the store', 'For each $10 of a paid store order.', 17), ('order_cap', '20', 'Most plays per order', 'Upper limit of plays from one store order.', 18), ('plays_referral', '2', 'Plays per referral', 'For the referrer, when someone new signs in for the first time through their link.', 19), ('referral_cap_month', '10', 'Most referral plays a month', 'Upper limit of referral plays one player can earn in a calendar month (Pacific).', 20), ('claim_how', 'Complete a set and press Claim prize on the board. RB reviews each claim and contacts you at the verified email on your account to arrange the prize.', 'How to claim', 'Shown in the official rules and on the board.', 30), ('free_entry', '', 'Free way to get plays by request', 'Optional. If you offer a free way to request plays (for example by email or mail), describe it here and it is shown in the official rules. Ask your legal reviewer whether you need one.', 31);
